"""Types covering each schema pattern generated by Bonsai.Sgen."""

from datetime import datetime, timedelta
from typing import Annotated, Literal

from pydantic import Field
from typing_extensions import TypeAliasType

from bonsai.sgen import DiscriminatedUnion, SchemaAlias, SchemaEnum, SchemaModel, SchemaUnion

from . import base

SGEN_NAMESPACE = "TestHelper.Derived"


class Color(SchemaEnum):
    """Specifies the available colors."""

    RED = 1
    DARK_BLUE = 2
    LightGreen = 10


class Mood(str, SchemaEnum):
    """Specifies the available moods."""

    HAPPY = "happy"
    VERY_SAD = "very sad"


class Cat(SchemaModel):
    """A member of several unions."""

    kind: Literal["cat"] = "cat"
    name: str
    lives: int = 9


class Hamster(SchemaModel):
    """A hamster."""

    kind: Literal["hamster"] = "hamster"
    name: str


class Animal(SchemaUnion):
    """A union including a member generated in another namespace."""

    root: Annotated[Cat | base.Dog, Field(discriminator="kind")]


class Pet(SchemaUnion):
    """A union sharing a member with another union."""

    root: Annotated[Cat | Hamster, Field(discriminator="kind")]


class Parrot(SchemaModel):
    """A union member that declares no tag."""

    name: str
    words: int = 0


class Goldfish(SchemaModel):
    """A union member that declares no tag."""

    name: str


class Creature(SchemaUnion):
    """A union assigning the tags of its members."""

    root: Annotated[Parrot | Goldfish, DiscriminatedUnion("species")]


Companion = TypeAliasType(
    "Companion", Annotated[Cat | Hamster, Field(discriminator="kind"), SchemaAlias()]
)
"""A union declared as a type alias."""

Flock = TypeAliasType(
    "Flock", Annotated[Parrot | Goldfish, DiscriminatedUnion("species"), SchemaAlias()]
)
"""A union alias assigning the tags of its members."""


class Home(SchemaModel):
    """A model referring to unions declared as type aliases."""

    companion: Companion
    companions: list[Companion] = []
    flock: Flock | None = None


class Palette(SchemaModel):
    """A choice of colors and moods."""

    color: Color = Color.RED
    favorite: Color | None = None
    mood: Mood = Mood.HAPPY


class Owner(SchemaModel):
    """A model with the common property types."""

    name: str
    age: int | None = None
    weight: float = 0.0
    nicknames: list[str] = []
    animal: Animal
    pets: list[Pet] = []
    friends: dict[str, Cat] = {}
    creature: Creature | None = None


Label = TypeAliasType("Label", str)
"""An alias of a scalar type."""

Nickname = TypeAliasType("Nickname", Label | None)
"""An alias of a nullable scalar type."""

Labels = TypeAliasType("Labels", list[Label])
"""An alias of a list."""

Counts = TypeAliasType("Counts", dict[str, int] | None)
"""An alias of a nullable dictionary."""


class Tag(SchemaModel):
    """A model referring to aliases of scalar types and collections."""

    label: Label
    nickname: Nickname = None
    aliases: Labels = []
    counts: Counts = None


class Kitten(Cat):
    """A subclass of a union member that declares its own tag."""


class Parakeet(Parrot):
    """A subclass of a union member tagged by its union."""


class Nursery(SchemaModel):
    """A model with properties typed as subclasses of union members."""

    kitten: Kitten | None = None
    parakeet: Parakeet | None = None


class Finch(SchemaModel):
    """A union member that declares no tag."""

    name: str


class Canary(Finch):
    """A union member deriving from another member of the same union."""

    song: str = ""


Songbird = TypeAliasType("Songbird", Annotated[Canary | Finch, DiscriminatedUnion("species")])
"""A union with a member deriving from another member."""


class Aviary(SchemaModel):
    """A model referring to a union with a member deriving from another member."""

    songbird: Songbird


class Owl(SchemaModel):
    """The only member of a union."""

    kind: Literal["owl"] = "owl"
    name: str


class Nightbird(SchemaUnion):
    """A union with a single member, kept as a union so members can be added."""

    root: Annotated[Owl, Field(discriminator="kind")]


class Kiwi(SchemaModel):
    """The only member of a union alias."""

    kind: Literal["kiwi"] = "kiwi"
    name: str


Flightless = TypeAliasType(
    "Flightless", Annotated[Kiwi, Field(discriminator="kind"), SchemaAlias()]
)
"""A union alias with a single member."""


class Roost(SchemaModel):
    """A model referring to unions with a single member."""

    nightbird: Nightbird | None = None
    flightless: Flightless | None = None


class Visit(SchemaModel):
    """A visit to the veterinarian."""

    start: datetime
    duration: timedelta | None = None
